#include <vector>
#include <omp.h>

void prefixSum(std::vector<double> const& x, std::vector<double> &output) {
    const std::size_t n = x.size();
    output.resize(n);
    if (n == 0) return;

    int P = 1;
    #pragma omp parallel
    {
        #pragma omp single
        { P = omp_get_num_threads(); }
    }

    std::vector<double> blockSums(static_cast<std::size_t>(P) + 1, 0.0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const std::size_t chunk = (n + static_cast<std::size_t>(nt) - 1) / static_cast<std::size_t>(nt);
        const std::size_t begin = static_cast<std::size_t>(tid) * chunk;
        const std::size_t end   = (begin + chunk < n) ? (begin + chunk) : n;

        double localSum = 0.0;
        for (std::size_t i = begin; i < end; ++i) {
            localSum += x[i];
            output[i] = localSum;
        }

        // Each thread writes its own block sum; no races.
        blockSums[static_cast<std::size_t>(tid) + 1] = localSum;

        #pragma omp barrier

        // Single thread computes prefix of block sums (offsets).
        #pragma omp single
        {
            for (int t = 1; t <= nt; ++t) {
                blockSums[static_cast<std::size_t>(t)] += blockSums[static_cast<std::size_t>(t) - 1];
            }
        }

        const double offset = blockSums[static_cast<std::size_t>(tid)];
        for (std::size_t i = begin; i < end; ++i) {
            output[i] += offset;
        }
    }
}
